const listDueIssueWorkflowActions = `-- name: ListDueIssueWorkflowActions :many
SELECT id, workspace_id, issue_id, action_key, request_hash, command_id, action_type, state, revision, operation_id, decision_id, release_id, notification_id, target_key, payload, not_before, lease_token, lease_expires_at, attempt_count, max_attempts, committed_at, settled_at, last_error, created_at, updated_at, lease_count, effect_attempt_count, observation_failure_count, effect_key, effect_result, reconciliation_state, last_observed_at, bound_task_id FROM issue_workflow_action_receipt
WHERE action_type IN ('review_correction', 'review_candidate', 'finalize_non_live', 'resume_exact_operation', 'replan_exact_operation', 'deploy_exact_release', 'expose_exact_release', 'verify_runtime_exact_release', 'verify_business_exact_release', 'monitor_exact_release', 'rollback_exact_release', 'verify_restoration_exact_release')
  AND (
    (state IN ('admitted', 'retry_wait', 'reconciling') AND not_before <= $1)
    OR (state = 'leased' AND lease_expires_at <= $1)
  )
ORDER BY CASE WHEN state = 'leased' THEN lease_expires_at ELSE not_before END, created_at, id
LIMIT $2
`

type ListDueIssueWorkflowActionsParams struct {
	Now       pgtype.Timestamptz `json:"now"`
	BatchSize int32              `json:"batch_size"`
}

func (q *Queries) ListDueIssueWorkflowActions(ctx context.Context, arg ListDueIssueWorkflowActionsParams) ([]IssueWorkflowActionReceipt, error) {
	rows, err := q.db.Query(ctx, listDueIssueWorkflowActions, arg.Now, arg.BatchSize)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []IssueWorkflowActionReceipt{}
	for rows.Next() {
		var i IssueWorkflowActionReceipt
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.IssueID,
			&i.ActionKey,
			&i.RequestHash,
			&i.CommandID,
			&i.ActionType,
			&i.State,
			&i.Revision,
			&i.OperationID,
			&i.DecisionID,
			&i.ReleaseID,
			&i.NotificationID,
			&i.TargetKey,
			&i.Payload,
			&i.NotBefore,
			&i.LeaseToken,
			&i.LeaseExpiresAt,
			&i.AttemptCount,
			&i.MaxAttempts,
			&i.CommittedAt,
			&i.SettledAt,
			&i.LastError,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.LeaseCount,
			&i.EffectAttemptCount,
			&i.ObservationFailureCount,
			&i.EffectKey,
			&i.EffectResult,
			&i.ReconciliationState,
			&i.LastObservedAt,
			&i.BoundTaskID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

